type VkImageLayout VkEnum
const (
	/*
	VK_IMAGE_LAYOUT_UNDEFINED Implicit layout an image is when its contents are undefined due to various reasons (e.g. right after creation)
	*/
	VK_IMAGE_LAYOUT_UNDEFINED VkImageLayout = 0

	/*
	VK_IMAGE_LAYOUT_GENERAL General layout when image can be used for any kind of access
	*/
	VK_IMAGE_LAYOUT_GENERAL VkImageLayout = 1

	/*
	VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL Optimal layout when image is only used for color attachment read/write
	*/
	VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL VkImageLayout = 2

	/*
	VK_IMAGE_LAYOUT_DEPTH_STENCIL_ATTACHMENT_OPTIMAL Optimal layout when image is only used for depth/stencil attachment read/write
	*/
	VK_IMAGE_LAYOUT_DEPTH_STENCIL_ATTACHMENT_OPTIMAL VkImageLayout = 3

	/*
	VK_IMAGE_LAYOUT_DEPTH_STENCIL_READ_ONLY_OPTIMAL Optimal layout when image is used for read only depth/stencil attachment and shader access
	*/
	VK_IMAGE_LAYOUT_DEPTH_STENCIL_READ_ONLY_OPTIMAL VkImageLayout = 4

	/*
	VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL Optimal layout when image is used for read only shader access
	*/
	VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL VkImageLayout = 5

	/*
	VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL Optimal layout when image is used only as source of transfer operations
	*/
	VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL VkImageLayout = 6

	/*
	VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL Optimal layout when image is used only as destination of transfer operations
	*/
	VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL VkImageLayout = 7

	/*
	VK_IMAGE_LAYOUT_PREINITIALIZED Initial layout used when the data is populated by the CPU
	*/
	VK_IMAGE_LAYOUT_PREINITIALIZED VkImageLayout = 8
)

