/*
VkResult API result codes
*/
type VkResult VkEnum
const (
	/*
	VK_SUCCESS Return codes (positive values)
	
	Command completed successfully
	*/
	VK_SUCCESS VkResult = 0

	/*
	VK_NOT_READY Return codes (positive values)
	
	A fence or query has not yet completed
	*/
	VK_NOT_READY VkResult = 1

	/*
	VK_TIMEOUT Return codes (positive values)
	
	A wait operation has not completed in the specified time
	*/
	VK_TIMEOUT VkResult = 2

	/*
	VK_EVENT_SET Return codes (positive values)
	
	An event is signaled
	*/
	VK_EVENT_SET VkResult = 3

	/*
	VK_EVENT_RESET Return codes (positive values)
	
	An event is unsignaled
	*/
	VK_EVENT_RESET VkResult = 4

	/*
	VK_INCOMPLETE Return codes (positive values)
	
	A return array was too small for the result
	*/
	VK_INCOMPLETE VkResult = 5

	/*
	VK_ERROR_OUT_OF_HOST_MEMORY Error codes (negative values)
	
	A host memory allocation has failed
	*/
	VK_ERROR_OUT_OF_HOST_MEMORY VkResult = -1

	/*
	VK_ERROR_OUT_OF_DEVICE_MEMORY Error codes (negative values)
	
	A device memory allocation has failed
	*/
	VK_ERROR_OUT_OF_DEVICE_MEMORY VkResult = -2

	/*
	VK_ERROR_INITIALIZATION_FAILED Error codes (negative values)
	
	Initialization of an object has failed
	*/
	VK_ERROR_INITIALIZATION_FAILED VkResult = -3

	/*
	VK_ERROR_DEVICE_LOST Error codes (negative values)
	
	The logical device has been lost. See <<devsandqueues-lost-device>>
	*/
	VK_ERROR_DEVICE_LOST VkResult = -4

	/*
	VK_ERROR_MEMORY_MAP_FAILED Error codes (negative values)
	
	Mapping of a memory object has failed
	*/
	VK_ERROR_MEMORY_MAP_FAILED VkResult = -5

	/*
	VK_ERROR_LAYER_NOT_PRESENT Error codes (negative values)
	
	Layer specified does not exist
	*/
	VK_ERROR_LAYER_NOT_PRESENT VkResult = -6

	/*
	VK_ERROR_EXTENSION_NOT_PRESENT Error codes (negative values)
	
	Extension specified does not exist
	*/
	VK_ERROR_EXTENSION_NOT_PRESENT VkResult = -7

	/*
	VK_ERROR_FEATURE_NOT_PRESENT Error codes (negative values)
	
	Requested feature is not available on this device
	*/
	VK_ERROR_FEATURE_NOT_PRESENT VkResult = -8

	/*
	VK_ERROR_INCOMPATIBLE_DRIVER Error codes (negative values)
	
	Unable to find a Vulkan driver
	*/
	VK_ERROR_INCOMPATIBLE_DRIVER VkResult = -9

	/*
	VK_ERROR_TOO_MANY_OBJECTS Error codes (negative values)
	
	Too many objects of the type have already been created
	*/
	VK_ERROR_TOO_MANY_OBJECTS VkResult = -10

	/*
	VK_ERROR_FORMAT_NOT_SUPPORTED Error codes (negative values)
	
	Requested format is not supported on this device
	*/
	VK_ERROR_FORMAT_NOT_SUPPORTED VkResult = -11

	/*
	VK_ERROR_FRAGMENTED_POOL Error codes (negative values)
	
	A requested pool allocation has failed due to fragmentation of the pool's memory
	*/
	VK_ERROR_FRAGMENTED_POOL VkResult = -12

	/*
	VK_ERROR_UNKNOWN Error codes (negative values)
	
	An unknown error has occurred, due to an implementation or application bug
	*/
	VK_ERROR_UNKNOWN VkResult = -13
)

